async function readVectorIds(db, key) {
  const row = await db.prepare(
    "SELECT vector_ids_json FROM memory_index_state WHERE memory_key = ?",
  ).bind(key).first();
  if (!row?.vector_ids_json) return [];
  try {
    const ids = JSON.parse(row.vector_ids_json);
    return Array.isArray(ids) ? ids : [];
  } catch {
    return [];
  }
}

async function exactSearch(db, query, filters, limit) {
  const where = ["instr(lower(chunk_text), lower(?)) > 0"];
  const binds = [query];
  addSqlFilters(where, binds, filters);
  const sql = `SELECT vector_id, memory_key, chunk_index, chunk_text, category, owner, memory_date
               FROM memory_chunks WHERE ${where.join(" AND ")} LIMIT ?`;
  const result = await db.prepare(sql).bind(...binds, limit).all();
  return result.results || [];
}

async function exactSearchForSpaces(db, query, filters, limit, spaceIds) {
  if (!spaceIds.length) return [];
  const where = ["instr(lower(mc.chunk_text), lower(?)) > 0"];
  const binds = [query];
  addSqlFilters(where, binds, filters, "mc.");
  const spaces = spaceIds.map(() => "?").join(",");
  where.push(`COALESCE(mks.space_id, ?) IN (${spaces})`);
  binds.push(LEGACY_SPACE_ID, ...spaceIds);
  const sql = `SELECT mc.vector_id, mc.memory_key, mc.chunk_index, mc.chunk_text,
                      mc.category, mc.owner, mc.memory_date, mc.content_hash, mc.index_version,
                      COALESCE(mks.space_id, ?) AS space_id
               FROM memory_chunks mc
               LEFT JOIN memory_key_spaces mks ON mks.memory_key = mc.memory_key
               WHERE ${where.join(" AND ")} LIMIT ?`;
  const result = await db.prepare(sql).bind(LEGACY_SPACE_ID, ...binds, limit).all();
  return result.results || [];
}

async function loadIndexedChunksByIds(db, ids, spaceIds = null) {
  if (!ids.length) return [];
  const placeholders = ids.map(() => "?").join(",");
  if (spaceIds) {
    if (!spaceIds.length) return [];
    const spaces = spaceIds.map(() => "?").join(",");
    const result = await db.prepare(
      `SELECT mc.vector_id, mc.memory_key, mc.chunk_index, mc.chunk_text,
              mc.category, mc.owner, mc.memory_date, mc.content_hash, mc.index_version,
              COALESCE(mks.space_id, ?) AS space_id
       FROM memory_chunks mc
       LEFT JOIN memory_key_spaces mks ON mks.memory_key = mc.memory_key
       WHERE mc.vector_id IN (${placeholders})
         AND COALESCE(mks.space_id, ?) IN (${spaces})`,
    ).bind(LEGACY_SPACE_ID, ...ids, LEGACY_SPACE_ID, ...spaceIds).all();
    return result.results || [];
  }
  const result = await db.prepare(
    `SELECT vector_id, memory_key, chunk_index, chunk_text, category, owner, memory_date
     FROM memory_chunks WHERE vector_id IN (${placeholders})`,
  ).bind(...ids).all();
  return result.results || [];
}

function addSqlFilters(where, binds, filters, prefix = "") {
  if (filters.category) { where.push(`${prefix}category = ?`); binds.push(filters.category); }
  if (filters.owner) { where.push(`${prefix}owner = ?`); binds.push(filters.owner); }
  if (filters.dateFrom) { where.push(`${prefix}memory_date >= ?`); binds.push(filters.dateFrom); }
  if (filters.dateTo) { where.push(`${prefix}memory_date <= ?`); binds.push(filters.dateTo); }
}

function buildVectorFilter(filters, spaceIds = null) {
  const filter = {};
  if (filters.category) filter.cat = filters.category;
  if (filters.owner) filter.owner = filters.owner;
  if (filters.dateFrom || filters.dateTo) {
    filter.date = {};
    if (filters.dateFrom) filter.date.$gte = filters.dateFrom;
    if (filters.dateTo) filter.date.$lte = filters.dateTo;
  }
  if (spaceIds) {
    if (!spaceIds.length) throw new Error("client has no recall-capable spaces");
    filter.space = spaceIds.length === 1 ? spaceIds[0] : { $in: spaceIds };
  }
  return filter;
}

async function semanticSearch(env, query, filters, spaceIds = null) {
  const [embedding] = await getEmbeddings([buildQueryText(query)], env);
  const filter = buildVectorFilter(filters, spaceIds);
  const options = { topK: VECTOR_CANDIDATES, returnMetadata: "all" };
  if (Object.keys(filter).length) options.filter = filter;
  const result = await env.VECTORIZE_INDEX.query(embedding, options);
  const matches = Array.isArray(result?.matches) ? result.matches : [];
  const rows = await loadIndexedChunksByIds(env.DB, matches.map(({ id }) => id), spaceIds);
  return { matches, rows };
}

function internalCandidate(row, query, semanticScore, exactSource) {
  return {
    ...scoreCandidate(row, query, semanticScore, exactSource),
    vectorId: row.vector_id,
    spaceId: row.space_id || null,
    contentHash: row.content_hash || null,
    indexVersion: row.index_version || INDEX_VERSION,
  };
}

function publicSearchItem(item) {
  return {
    key: item.key,
    chunkIndex: item.chunkIndex,
    category: item.category,
    owner: item.owner,
    date: item.date,
    score: item.score,
    semanticScore: item.semanticScore,
    exactMatch: item.exactMatch,
    chunk: item.chunk,
  };
}

async function listAllKeys(kv, options = {}) {
  const keys = [];
  let cursor;
  do {
    const page = await kv.list({ cursor, limit: 1_000, prefix: options.prefix });
    keys.push(...page.keys.map(({ name }) => name));
    cursor = page.list_complete ? undefined : page.cursor;
  } while (cursor);
  return keys;
}

function buildEmbeddingText(key, meta, chunk) {
  return [
    `Key: ${key}`,
    `Category: ${meta.category}`,
    `Owner: ${meta.owner}`,
    meta.date ? `Date: ${meta.date}` : "",
    "",
    chunk,
  ].filter((line) => line !== "").join("\n");
}

function buildQueryText(query) {
  return `为中文个人记忆库检索相关片段。查询：${query}`;
}

async function getEmbeddings(texts, env) {
  const result = await env.AI.run(EMBEDDING_MODEL, { text: texts });
  const data = result?.data || result?.result?.data;
  if (!Array.isArray(data)) throw new Error("unrecognized embedding response");
  if (Array.isArray(data[0])) return data;
  if (data[0]?.embedding) return data.map((item) => item.embedding);
  throw new Error("embedding response contains no vectors");
}

async function sha256Hex(value) {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(String(value)));
  return [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, "0")).join("");
}

function isAuthorized(request, token) {
  return typeof token === "string"
    && token.length >= MIN_BEARER_TOKEN_LENGTH
    && request.headers.get("Authorization") === `Bearer ${token}`;
}

function isAuthorizedUrlPath(pathname, token) {
  return typeof token === "string"
    && token.length >= MIN_URL_TOKEN_LENGTH
    && URL_TOKEN_PATTERN.test(token)
    && pathname === `/mcp/${token}`;
}

function memoryToken(env) {
  return env.MEMORY_TOKEN || env.AUTH_TOKEN;
}

function urlToken(env) {
  return env.MEMORY_TOKEN || env.MCP_URL_TOKEN;
}

function authMode(env) {
  return String(env.V9_AUTH_MODE || "off").toLowerCase() === V9_MODE_SHADOW ? V9_MODE_SHADOW : "off";
}

function recallEnabled(env) {
  return authMode(env) === V9_MODE_SHADOW
    && String(env.V9_RECALL_ENABLED || "false").toLowerCase() === V9_RECALL_FLAG;
}

function infraEnabled(env) {
  return authMode(env) === V9_MODE_SHADOW
    && String(env.V9_INFRA_ENABLED || "false").toLowerCase() === V9_INFRA_FLAG;
}

function legacyAuthContext(kind = "legacy-bearer") {
  return { legacy: true, kind, clientId: null, grants: [] };
}

async function authenticateMcpRequest(request, env) {
  if (isAuthorized(request, memoryToken(env))) return legacyAuthContext();
  if (authMode(env) !== V9_MODE_SHADOW || !env.DB) return null;
  const header = request.headers.get("Authorization") || "";
  const match = header.match(/^Bearer\s+(.+)$/i);
  if (!match || match[1].length < MIN_BEARER_TOKEN_LENGTH) return null;
  return authenticateIsolatedToken(match[1], env, "isolated-bearer", false);
}

function urlPathToken(pathname) {
  const match = pathname.match(/^\/mcp\/([A-Za-z0-9_-]+)$/);
  return match ? match[1] : null;
}

async function authenticateUrlRequest(token, env) {
  if (isAuthorizedUrlPath(`/mcp/${token}`, urlToken(env))) return legacyAuthContext("legacy-url");
  if (!infraEnabled(env) || !token || token.length < MIN_BEARER_TOKEN_LENGTH) return null;
  return authenticateIsolatedToken(token, env, "isolated-url", true);
}

async function authenticateIsolatedToken(token, env, kind, requireUrlAllowed) {
  const tokenHash = await sha256Hex(token);
  const useInfra = infraEnabled(env);
  const client = useInfra
    ? await env.DB.prepare(
      `SELECT c.client_id, c.client_name,
              COALESCE(p.borrow_enabled, 0) AS borrow_enabled,
              COALESCE(p.borrow_daily_limit, 20) AS borrow_daily_limit,
              COALESCE(p.isolated_url_auth_enabled, 0) AS isolated_url_auth_enabled
       FROM api_clients c LEFT JOIN api_client_policies p ON p.client_id=c.client_id
       WHERE c.token_hash = ? AND c.revoked_at IS NULL
         AND (c.expires_at IS NULL OR datetime(c.expires_at) > CURRENT_TIMESTAMP)`,
    ).bind(tokenHash).first()
    : await env.DB.prepare(
      `SELECT client_id, client_name
       FROM api_clients
       WHERE token_hash = ? AND revoked_at IS NULL
         AND (expires_at IS NULL OR datetime(expires_at) > CURRENT_TIMESTAMP)`,
    ).bind(tokenHash).first();
  if (!client) return null;
  if (requireUrlAllowed && Number(client.isolated_url_auth_enabled) !== 1) return null;
  const rows = await env.DB.prepare(
    `SELECT g.space_id, s.space_key, g.capability
     FROM api_client_space_grants g
     JOIN memory_spaces s ON s.space_id = g.space_id
     WHERE g.client_id = ? AND g.revoked_at IS NULL AND s.disabled_at IS NULL
       AND (g.expires_at IS NULL OR datetime(g.expires_at) > CURRENT_TIMESTAMP)`,
  ).bind(client.client_id).all();
  const borrowRows = useInfra && Number(client.borrow_enabled) === 1
    ? await env.DB.prepare(
      `SELECT b.target_space_id AS space_id, s.space_key
       FROM api_client_borrow_spaces b JOIN memory_spaces s ON s.space_id=b.target_space_id
       WHERE b.client_id=? AND b.revoked_at IS NULL AND s.disabled_at IS NULL
         AND (b.expires_at IS NULL OR datetime(b.expires_at) > CURRENT_TIMESTAMP)`,
    ).bind(client.client_id).all()
    : { results: [] };
  return {
    legacy: false,
    kind,
    clientId: client.client_id,
    clientName: client.client_name,
    grants: rows.results || [],
    borrowEnabled: useInfra && Number(client.borrow_enabled) === 1,
    borrowDailyLimit: Number(client.borrow_daily_limit || 20),
    borrowSpaces: borrowRows.results || [],
  };
}

function visibleTools(auth, env) {
  if (auth.legacy) return TOOLS.filter((tool) => (
    (!tool.v9Only && !tool.v9InfraOnly) || (tool.name === "rename_memory" && infraEnabled(env))
  )).map(stripInternalToolFields);
  return TOOLS.filter((tool) => {
    if (tool.v9Only && !recallEnabled(env)) return false;
    if (tool.v9InfraOnly && !infraEnabled(env)) return false;
    if (tool.name === "borrow_memory") return auth.borrowEnabled && (auth.borrowSpaces || []).length > 0;
    if (tool.name === "rename_memory") return renameGrantedSpaceIds(auth).length > 0;
    const capability = TOOL_CAPABILITIES[tool.name];
    return capability && grantedSpaceIds(auth, capability).length > 0;
  }).map((tool) => {
    const clean = stripInternalToolFields(tool);
    if (clean.name === "delete_memory" && infraEnabled(env)) {
      clean.description = "Soft-delete one key into a recoverable recycle record when confirmKey exactly matches key.";
    }
    if (!new Set(["save_memory", "save_daily"]).has(clean.name)) return clean;
    return {
      ...clean,
      inputSchema: {
        ...clean.inputSchema,
        properties: {
          ...clean.inputSchema.properties,
          spaceKey: { type: "string", maxLength: 80 },
        },
        required: [...new Set([...(clean.inputSchema.required || []), "spaceKey"])],
        additionalProperties: false,
      },
    };
  });
}

function stripInternalToolFields({ v9Only, v9InfraOnly, ...tool }) {
  return tool;
}

function assertToolAuthorized(auth, toolName, env) {
  const tool = TOOLS.find(({ name }) => name === toolName);
  if (!tool) throw new Error(`Unknown tool: ${toolName}`);
  if (auth.legacy) {
    if (tool.name === "rename_memory" && infraEnabled(env)) return;
    if (tool.v9Only || tool.v9InfraOnly) throw new Error("tool is unavailable on the legacy channel");
    return;
  }
  if (tool.v9Only && !recallEnabled(env)) throw new Error("recall tools are disabled");
  if (tool.v9InfraOnly && !infraEnabled(env)) throw new Error("infrastructure tools are disabled");
  if (toolName === "borrow_memory") {
    if (!auth.borrowEnabled || !(auth.borrowSpaces || []).length) throw new Error("borrow is not enabled");
    return;
  }
  if (toolName === "rename_memory") {
    if (!renameGrantedSpaceIds(auth).length) throw new Error("rename requires write and delete grants for the same space");
    return;
  }
  const capability = TOOL_CAPABILITIES[toolName];
  if (!capability || !grantedSpaceIds(auth, capability).length) {
    throw new Error("client is not authorized for this tool");
  }
}

function renameGrantedSpaceIds(auth) {
  const writable = new Set(grantedSpaceIds(auth, "write"));
  return grantedSpaceIds(auth, "delete").filter((spaceId) => writable.has(spaceId));
}

function grantedSpaceIds(auth, capability) {
  return [...new Set((auth.grants || [])
    .filter((grant) => grant.capability === capability)
    .map((grant) => grant.space_id))];
}

function assertSpaceCapability(auth, spaceId, capability) {
  if (auth.legacy) return;
  if (!(auth.grants || []).some((grant) => grant.space_id === spaceId && grant.capability === capability)) {
    throw new Error("client is not authorized for this memory space");
  }
}

async function requireSpaceGrant(auth, spaceKey, capability, env) {
  const normalized = normalizeSpaceKey(spaceKey);
  const grant = (auth.grants || []).find((item) => item.space_key === normalized && item.capability === capability);
  if (!grant) throw new Error("client is not authorized for this memory space");
  const space = await env.DB.prepare(
    "SELECT space_id, space_key FROM memory_spaces WHERE space_id = ? AND disabled_at IS NULL",
  ).bind(grant.space_id).first();
  if (!space) throw new Error("memory space is disabled or missing");
  return { spaceId: space.space_id, spaceKey: space.space_key };
}

async function readKeySpace(db, key) {
  return db.prepare(
    `SELECT mks.space_id, s.space_key, s.disabled_at
     FROM memory_key_spaces mks JOIN memory_spaces s ON s.space_id = mks.space_id
     WHERE mks.memory_key = ?`,
  ).bind(key).first();
}

async function requireKeyCapability(auth, key, capability, env) {
  const mapping = await readKeySpace(env.DB, key);
  const spaceId = mapping?.space_id || LEGACY_SPACE_ID;
  assertSpaceCapability(auth, spaceId, capability);
  return { spaceId, spaceKey: mapping?.space_key || "legacy-unclassified" };
}

async function insertKeySpace(db, key, spaceId, source = "explicit") {
  const result = await db.prepare(
    `INSERT INTO memory_key_spaces (memory_key, space_id, assignment_source)
     VALUES (?, ?, ?)
     ON CONFLICT(memory_key) DO NOTHING`,
  ).bind(key, spaceId, source).run();
  return Number(result.meta?.changes || 0) > 0;
}

async function acquireKeyMutationLock(db, key) {
  const lockId = crypto.randomUUID();
  const result = await db.prepare(
    `INSERT INTO memory_key_operation_locks (memory_key, lock_id, expires_at)
     VALUES (?, ?, datetime(CURRENT_TIMESTAMP, '+10 minutes'))
     ON CONFLICT(memory_key) DO UPDATE SET
       lock_id=excluded.lock_id, expires_at=excluded.expires_at
     WHERE datetime(memory_key_operation_locks.expires_at) <= CURRENT_TIMESTAMP`,
  ).bind(key, lockId).run();
  if (Number(result.meta?.changes || 0) < 1) throw new Error("another operation is in progress for this key");
  return lockId;
}

async function acquireKeyMutationLocks(db, keys) {
  const locks = [];
  try {
    for (const key of [...new Set(keys)].sort()) {
      locks.push({ key, lockId: await acquireKeyMutationLock(db, key) });
    }
    return locks;
  } catch (error) {
    await releaseKeyMutationLocks(db, locks);
    throw error;
  }
}

async function releaseKeyMutationLocks(db, locks) {
  for (const { key, lockId } of [...locks].reverse()) await releaseKeyMutationLock(db, key, lockId);
}

async function replaceRenameProtectionList(env, body) {
  const sourceVersion = normalizeLabel(body.sourceVersion, "sourceVersion");
  if (!Array.isArray(body.keys) || !body.keys.length || body.keys.length > 100) {
    throw new Error("keys must contain 1-100 protected-key entries");
  }
  const rows = [];
  const seen = new Set();
  for (const item of body.keys) {
    const key = String(item?.key || "");
    validateKeyValue(key, "");
    const reason = normalizeLabel(item?.reason, "reason");
    if (seen.has(key)) throw new Error("protected keys must be unique");
    seen.add(key);
    rows.push({ key, reason });
  }
  rows.sort((left, right) => left.key.localeCompare(right.key));
  const sourceDigest = await sha256Hex(JSON.stringify({ sourceVersion, rows }));
  await env.DB.prepare(
    "UPDATE memory_rename_policy_state SET protected_keys_ready=0, updated_at=CURRENT_TIMESTAMP WHERE singleton=1",
  ).run();
  const statements = [env.DB.prepare("DELETE FROM memory_rename_protected_keys")];
  for (const row of rows) statements.push(env.DB.prepare(
    "INSERT INTO memory_rename_protected_keys (memory_key, reason, source_version) VALUES (?, ?, ?)",
  ).bind(row.key, row.reason, sourceVersion));
  statements.push(env.DB.prepare(
    `UPDATE memory_rename_policy_state SET protected_keys_ready=1, source_version=?, source_digest=?,
     updated_at=CURRENT_TIMESTAMP WHERE singleton=1 AND protected_keys_ready=0`,
  ).bind(sourceVersion, sourceDigest));
  await env.DB.batch(statements);
  return { protectedKeyCount: rows.length, sourceVersion, sourceDigest, ready: true };
}

async function reconcileMemoryRenames(env, limit) {
  const rows = await env.DB.prepare(
    `SELECT operation_id, old_key, new_key, status, content_hash, old_vector_ids_json
     FROM memory_rename_journal
     WHERE status IN ('rollback_required','committed','reconcile_required')
        OR (status='pending' AND datetime(started_at)<=datetime('now','-20 minutes'))
     ORDER BY started_at, operation_id LIMIT ?`,
  ).bind(limit).all();
  const summary = { examined: 0, repaired: 0, blocked: 0 };
  for (const row of rows.results || []) {
    summary.examined += 1;
    let locks = [];
    try {
      locks = await acquireKeyMutationLocks(env.DB, [row.old_key, row.new_key]);
      if (new Set(["pending", "rollback_required"]).has(row.status)) {
        if (await readKeySpace(env.DB, row.new_key)) throw new Error("target mapping is authoritative");
        const targetValue = await env.MEMORY.get(row.new_key);
        if (targetValue !== null && await sha256Hex(targetValue) !== row.content_hash) {
          throw new Error("target body changed");
        }
        await removeMemoryEverywhere(row.new_key, env, targetValue !== null, false);
        await updateRenameJournal(env.DB, row.operation_id, "rolled_back", null, ["pending", "rollback_required"]);
      } else {
        if (await readKeySpace(env.DB, row.old_key)) throw new Error("source mapping is still authoritative");
        const oldValue = await env.MEMORY.get(row.old_key);
        if (oldValue !== null && await sha256Hex(oldValue) !== row.content_hash) throw new Error("source body changed");
        const ids = parseVectorIds(row.old_vector_ids_json);
        if (ids.length) await env.VECTORIZE_INDEX.deleteByIds(ids);
        if (oldValue !== null) await env.MEMORY.delete(row.old_key);
        await updateRenameJournal(env.DB, row.operation_id, "success", null, ["committed", "reconcile_required"]);
      }
      summary.repaired += 1;
    } catch { summary.blocked += 1; }
    finally { await releaseKeyMutationLocks(env.DB, locks); }
  }
  return summary;
}

async function releaseKeyMutationLock(db, key, lockId) {
  try {
    await db.prepare(
      "DELETE FROM memory_key_operation_locks WHERE memory_key = ? AND lock_id = ?",
    ).bind(key, lockId).run();
  } catch {
    // Fail closed until the short lease expires.
  }
}

async function indexSpaceForRequest(auth, key, env) {
  if (authMode(env) !== V9_MODE_SHADOW || !auth.legacy) return null;
  return (await readKeySpace(env.DB, key))?.space_id || LEGACY_SPACE_ID;
}

function shouldMaintainMappings(auth, env) {
  return !auth.legacy || authMode(env) === V9_MODE_SHADOW;
}

function normalizeSpaceKey(value) {
  const normalized = String(value || "").trim().toLowerCase();
  if (!/^[a-z0-9][a-z0-9:.-]{0,79}$/.test(normalized)) {
    throw new Error("spaceKey must be 1-80 lowercase letters, numbers, colon, dot, or hyphen");
  }
  return normalized;
}

function landingPage() {
  return new Response([
    "personal-ai-memory V8 is running.",
    "",
    "MCP endpoint: /mcp (Bearer) or /mcp/<MEMORY_TOKEN> (URL-only clients).",
    "Keep MEMORY_TOKEN and ADMIN_TOKEN secret. This page never displays them.",
  ].join("\n"), {
    headers: { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store" },
  });
}

function safeError(error) {
  const message = error instanceof Error ? error.message : String(error);
  return message.slice(0, 500);
}

function rpcResult(id, result) {
  return { jsonrpc: "2.0", id, result };
}

function rpcError(id, code, message) {
  return { jsonrpc: "2.0", id, error: { code, message } };
}

function corsHeaders(env) {
  const headers = {
    "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type, Authorization",
    Vary: "Origin",
  };
  if (env.ALLOWED_ORIGIN) headers["Access-Control-Allow-Origin"] = env.ALLOWED_ORIGIN;
  return headers;
}

function jsonResponse(body, status, env) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { "Content-Type": "application/json; charset=utf-8", ...corsHeaders(env) },
  });
}

function corsResponse(env) {
  return new Response(null, { status: 204, headers: corsHeaders(env) });
}

function sseInit(env) {
  const payload = JSON.stringify({ jsonrpc: "2.0", method: "notifications/initialized", params: {} });
  return new Response(`data: ${payload}\n\n`, {
    headers: {
      "Content-Type": "text/event-stream",
      "Cache-Control": "no-cache",
      ...corsHeaders(env),
    },
  });
}

